WITH with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC) + INTERVAL 30 MINUTES THEN 1 ELSE 0 END AS session_start_flag FROM device_readings), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY device_code ORDER BY reading_ts ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT DATE_TRUNC('DAY', reading_ts) AS activity_day, device_code, burst_id, BIT_AND(status_bits) AS status_bits_bit_and, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list, SORT_ARRAY(COLLECT_SET(device_code)) AS device_code_list_2, GROUPING(DATE_TRUNC('DAY', reading_ts)) AS grouping_id FROM islands GROUP BY CUBE (DATE_TRUNC('DAY', reading_ts), device_code, burst_id) ORDER BY activity_day ASC;
